#!/usr/bin/env bash
# scripts/container/flash-crosscheck.sh — run Espressif's own tools over extracted flash regions.
#
# Runs INSIDE the espressif/idf container (mounted at /xz/container), never on the host.
# Started by scripts/33-crosscheck-idf-tools.sh:
#
#     xz_idf_run bash /xz/container/flash-crosscheck.sh /home/builder/flash-crosscheck
#
# <work-dir>/jobs.txt (written by scripts/py/crosscheck_idf.py prepare) lists what to do, one
# job per line, fields separated by blanks; file names are generated by us, never taken from
# an image:
#     table  <file>                          gen_esp32part.py: binary partition table -> CSV (verifies the MD5)
#     image  <file>                          esptool image-info: header, segments, checksum, hash, descriptor
#     nvsgen <csv> <out.bin> <size> <ver>    esp_idf_nvs_partition_gen: build an NVS image from a CSV
#     nvs    <file>                          nvs_tool.py -d minimal -f json: decode an NVS partition
# Every job writes <file>.out (stdout), <file>.err (stderr) and <file>.rc (exit status) next to
# its input file (for nvsgen: next to the CSV). Nothing is printed here except one status line
# per job: the outputs can contain NVS values, so they are only ever read by the host-side
# comparison, which prints no values.
#
# The tools only read files in <work-dir>; no network, no device, nothing outside <work-dir>
# is written.
set -uo pipefail

work="${1:?work dir}"
cd "$work" || { echo "flash-crosscheck: no such directory: $work" >&2; exit 2; }
[[ -f jobs.txt ]] || { echo "flash-crosscheck: jobs.txt missing in $work" >&2; exit 2; }
: "${IDF_PATH:?IDF_PATH is not set - not inside the ESP-IDF container?}"

gen_part="$IDF_PATH/components/partition_table/gen_esp32part.py"
nvs_tool="$IDF_PATH/components/nvs_flash/nvs_partition_tool/nvs_tool.py"

{
  printf 'idf_git_describe=%s\n' "$(git -C "$IDF_PATH" describe --tags --always 2>/dev/null || echo unknown)"
  printf 'esptool=%s\n' "$(python -c 'import esptool; print(esptool.__version__)' 2>/dev/null || echo unknown)"
  printf 'nvs_partition_gen=%s\n' "$(python -c 'from importlib.metadata import version; print(version("esp_idf_nvs_partition_gen"))' 2>/dev/null || echo unknown)"
} > tools.env

run_job() {   # run_job <output-base> <cmd...>
  local base="$1"; shift
  "$@" > "$base.out" 2> "$base.err"
  local rc=$?
  echo "$rc" > "$base.rc"
  return 0
}

while read -r kind a b c d _rest; do
  [[ -n "${kind:-}" ]] || continue
  case "$a$b" in *[!A-Za-z0-9._-]*) echo "flash-crosscheck: refusing odd file name in jobs.txt" >&2; exit 2 ;; esac
  case "$kind" in
    table)  run_job "$a" python "$gen_part" "$a" ;;
    image)  run_job "$a" esptool image-info "$a" ;;
    nvsgen) run_job "$a" python -m esp_idf_nvs_partition_gen generate --version "$d" "$a" "$b" "$c" ;;
    nvs)    run_job "$a" python "$nvs_tool" -d minimal -f json "$a" ;;
    *)      echo "flash-crosscheck: unknown job '$kind'" >&2; exit 2 ;;
  esac
  echo "ran: $kind $a (exit $(cat "$a.rc"))"
done < jobs.txt
